  "1. Fichier → Nouveau → Meuble, ou Ma bibliothèque : choisissez le meuble et ses cotes.\n2. Les pièces sont coupées dans la feuille et les liaisons notées (aperçu 3D à droite).\n3. Outils → Usiner : le meuble se monte, vis, tourillons, charnières, pieds et plinthe sont posés.\n4. Fichier → Plan de fabrication (PDF) pour l’atelier.": "1. File → New → Furniture, or My library: choose the furniture and its dimensions.\n2. The parts are cut from the sheet and the links noted (3D preview on the right).\n3. Tools → Machine: the furniture is assembled; screws, dowels, hinges, legs and plinth are placed.\n4. File → Manufacturing plan (PDF) for the workshop.",
