  "Touchez « Lier deux chants », puis le chant d’une pièce et celui où il se pose.": "Tap \"Link two edges\", then a part's edge and the one it rests on.",
  "Vérifiez l’aperçu monté à droite.": "Check the built preview on the right.",
  "Touchez « Monter le meuble ».": "Tap \"Build the unit\".",
  "{0} : {1} pièces coupées, {2} liaisons notées. Vérifiez l’aperçu 3D, puis « Monter le meuble ».": "{0}: {1} parts cut, {2} links noted. Check the 3D preview, then \"Build the unit\".",
  "{0} pièce(s) importée(s) à plat : touchez deux chants pour les lier, puis « Monter le meuble ».": "{0} part(s) imported flat: touch two edges to link them, then \"Build the unit\".",
  "Les pièces sont coupées à la guillotine (une feuille de plus si besoin) et les liaisons notées : vérifiez l’aperçu 3D, puis « Monter le meuble » pose vis, tourillons, charnières, pieds et plinthe.": "Parts are guillotine cut (one more sheet if needed) and links noted: check the 3D preview, then \"Build the unit\" adds screws, dowels, hinges, feet and plinth.",
  "1. Posez une feuille, puis « Couper » : touchez la feuille ou tapez la cote et Entrée.\n2. « Lier » : touchez deux chants, l’aperçu monté se met à jour.\n3. « Monter le meuble » assemble les pièces, vis et tourillons compris.\n4. Débit et plans : liste, plan de fabrication, SketchCut et stock.": "1. Lay a sheet, then \"Cut\": tap the sheet or type the size and Enter.\n2. \"Link\": tap two edges, the built preview updates.\n3. \"Build the unit\" assembles the parts, screws and dowels included.\n4. Cutting and plans: list, workshop plan, SketchCut and stock.",
