  "Tout meuble en bois a la même structure : côtés, bas, haut, derrière, séparations, étagères, puis portes, tiroirs, pieds et joues. On choisit une base, on la divise en colonnes et en étagères, puis on habille chaque zone.": "لكل خزانة خشبية البنية نفسها: الجوانب، القاع، السقف، الظهر، الفواصل، الرفوف، ثم الأبواب والأدراج والأرجل والألواح الجانبية. اختر قاعدة، قسّمها إلى أعمدة ورفوف، ثم جهّز كل منطقة.",
