  "Orange : chant plaqué. Gris : rainure. Cercle noir : perçage de face ; bleu : perçage dans le chant (au bord). X le long de la longueur, Y le long de la largeur, depuis le coin bas gauche.": "برتقالي: حافة ملصقة. رمادي: مجرى. دائرة سوداء: ثقب في الوجه؛ زرقاء: ثقب في الحافة. X على الطول، Y على العرض، من الزاوية السفلية اليسرى.",
  "Ordre de montage": "ترتيب التركيب",
  "Origine de chaque fiche : coin bas gauche de la pièce vue de sa face A (face vers l’avant, le haut ou la droite du meuble).": "أصل كل بطاقة: الزاوية السفلية اليسرى للقطعة من وجهها A (نحو أمام الأثاث أو أعلاه أو يمينه).",
