  "1. Fichier → Nouveau → Meuble, ou Ma bibliothèque : choisissez le meuble et ses cotes.\n2. Les pièces sont coupées dans la feuille et les liaisons notées (aperçu 3D à droite).\n3. Outils → Usiner : le meuble se monte, vis, tourillons, charnières, pieds et plinthe sont posés.\n4. Fichier → Plan de fabrication (PDF) pour l’atelier.": "1. ملف ← جديد ← قطعة أثاث، أو مكتبتي: اختر القطعة وأبعادها.\n2. تُقطع القطع من اللوح وتُسجَّل الوصلات (معاينة ثلاثية الأبعاد على اليمين).\n3. أدوات ← تشغيل: تُجمَّع القطعة وتوضع البراغي والأوتاد والمفصلات والأرجل والقاعدة.\n4. ملف ← مخطط التصنيع (PDF) للورشة.",
