  "{0} : {1} pièces coupées, {2} liaisons notées. Vérifiez l’aperçu 3D, puis « Monter le meuble ».": "{0}: {1} قطعة مقصوصة، {2} رابط. تحقق من المعاينة ثم «تركيب الأثاث».",
  "{0} pièce(s) importée(s) à plat : touchez deux chants pour les lier, puis « Monter le meuble ».": "{0} قطعة مستوردة: المس حافتين لربطهما ثم «تركيب الأثاث».",
  "Les pièces sont coupées à la guillotine (une feuille de plus si besoin) et les liaisons notées : vérifiez l’aperçu 3D, puis « Monter le meuble » pose vis, tourillons, charnières, pieds et plinthe.": "تُقص القطع بالمقصلة (لوح إضافي عند الحاجة) وتُسجل الروابط: تحقق من المعاينة ثم «تركيب الأثاث» يضع البراغي والأوتاد والمفصلات والأرجل والوزرة.",
  "1. Posez une feuille, puis « Couper » : touchez la feuille ou tapez la cote et Entrée.\n2. « Lier » : touchez deux chants, l’aperçu monté se met à jour.\n3. « Monter le meuble » assemble les pièces, vis et tourillons compris.\n4. Débit et plans : liste, plan de fabrication, SketchCut et stock.": "1. ضع لوحًا ثم «قص»: المس اللوح أو اكتب المقاس واضغط Enter.\n2. «ربط»: المس حافتين، تتحدث المعاينة.\n3. «تركيب الأثاث» يجمع القطع مع البراغي والأوتاد.\n4. القص والمخططات: القائمة ومخطط التصنيع وSketchCut والمخزون.",
